function toast(s){const t=document.createElement('div');t.className='toast';t.textContent=s;$('#toastWrap').append(t);setTimeout(()=>t.remove(),3200)}
function countDocs(prefix){return DOCS.filter(d=>d.path.startsWith(prefix)).length}
function setPage(id){state.view=id;document.title=`${names.get(id)||'Documento'} · Sol de Cobre`;$('#pageTitle').textContent=names.get(id)||'Documento';$('#breadcrumbs').textContent=`Sol de Cobre / ${id==='overview'?'Painel da arquitetura':names.get(id)||'Documento'}`;$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.id===id));if(window.matchMedia('(max-width:950px)').matches)closeMenu();main.scrollTop=0;window.scrollTo(0,0)}
function writeHash(value,replace=false){if(location.protocol==='file:'){location.hash=value;return;}history[replace?'replaceState':'pushState'](null,'','#'+value)}
function nav(id,sub){if(!names.has(id))id='overview';setPage(id);if(id==='explorer'&&sub){state.selected=decodeURIComponent(sub)};if(id==='docs'&&sub){state.selected=decodeURIComponent(sub)};render();let value=id+(sub?'/'+encodeURIComponent(sub):'');if(location.hash.slice(1)!==value)writeHash(value)}
function route(){let v=location.hash.replace(/^#/,'').split('/');const id=v.shift()||'overview';state.selected=v.length?decodeURIComponent(v.join('/')):state.selected;if(!names.has(id))return nav('overview');setPage(id);render()}
function setupNav(){$('#mainNav').innerHTML=groups.map(([group,links],i)=>`<div class="nav-cluster"><button type="button" class="nav-group" data-group="${i}" aria-expanded="true"><span>${group}</span>${icon('chevron-down')}</button><div class="nav-items">${links.map(([id,label,ic])=>`<button type="button" class="nav-item" data-action="navigate" data-id="${id}">${icon(ic)}<span>${label}</span></button>`).join('')}</div></div>`).join('');}
