const head=(tag,title,description,side='')=>`<div class="page-heading"><div><div class="eyebrow">${esc(tag)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${side}</div>`;
const section=(title,ico,side='')=>`<div class="section-title">${icon(ico)}<h2>${esc(title)}</h2><span class="section-side">${side}</span></div>`;
